NativeSignal sys0_set_archive_search(VM& vm, Thread& thread) {
    const std::string archive =
        vm.memory().read_cstring(thread.stack.pop(), thread.base);
    const uint32_t path_address = thread.stack.pop();
    const std::string path = path_address == 0
                                 ? std::string(".")
                                 : vm.memory().read_cstring(
                                       path_address, thread.base);
    const auto with_backslash = [](std::string value) {
        if (value.empty() ||
            (value.back() != '\\' && value.back() != '/')) {
            value.push_back('\\');
        }
        return value;
    };

    std::string base = vm.primary_directory();
    if (base.empty()) {
        base = ".";
    }
    base = with_backslash(base);
    vm.set_current_directory(base);
    vm.set_secondary_directory(base);
    vm.set_archive_search_state("system.arc", archive);
    if (path == ".") {
        return NativeSignal::Continue;
    }

    std::error_code error;
    const bool directory =
        host_files::is_directory(resolve_host_path(vm, path), error);
    std::string search_path;
    std::string source;
    if (!error && directory) {
        search_path = with_backslash(path);
        source = path;
    } else {
        const std::size_t separator = path.find_last_of("\\/");
        if (separator == std::string::npos) {
            source = path;
        } else {
            search_path = path.substr(0, separator + 1);
            std::replace(
                search_path.begin(), search_path.end(), '/', '\\');
            source = path.substr(separator + 1);
        }
        if (search_path.empty()) {
            search_path = base;
        }
    }
    vm.set_current_directory(search_path);
    vm.set_secondary_directory(search_path);
    vm.set_archive_search_state(source, archive);
    return NativeSignal::Continue;
}
